 html=re.sub(r'\s*·\s*<a href="guide\.html"><span data-l="en">guide</span><span data-l="fr">guide</span></a>','',html,count=1)
 html=re.sub(r'<script src="beat-diagnostic[^\"]+"></script>','',html)
 html=html.replace('midi-machine-all.js?', 'midi-machine-main.js?')
 html=re.sub(r'<title>.*?</title>','<title>Supermodel — Model:Cycles firmware</title>',html,count=1)
 html=html.replace('MIDI Out machine controls and test guide','MIDI Out machine controls').replace('Commandes et guide de test MIDI Out','Commandes MIDI Out')
 html=html.replace('Choose mods','Features').replace('Choisir les mods','Fonctions')
 html=html.replace('Pad Setup', 'Mod Setup').replace('dans Pad Setup sur l’appareil.', 'dans Mod Setup sur l’appareil.')
 html=re.sub(r'<p class="quick-reference"><a data-l="en" href="quick-reference\.md[^\"]*" download>.*?</p>', '', html, count=1)
 html=html.replace('<head>','<head><style>.super-search,.super-toolbar,.super-columns,#select-all-note,.mods-lede,#tab-samples{display:none!important}.fixed-features{max-width:850px}.fixed-features li{margin:.8em 0}</style>',1)
 listing='<div class="fixed-features"><h3><span data-l="en">Included features</span><span data-l="fr">Fonctions incluses</span></h3><p><span data-l="en">One complete firmware. All features below are included. USB audio starts in standard stereo (2ch); switch to six-channel audio from Mod Setup on the device.</span><span data-l="fr">Un firmware complet. Toutes les fonctions ci-dessous sont incluses. L’audio USB demarre en stereo standard (2ch) ; choisir six canaux dans Mod Setup sur l’appareil.</span></p><ul>'
 listing+=''.join('<li><span data-l="en">'+en+'</span><span data-l="fr">'+fr+'</span></li>' for en,fr in FEATURES)
 listing+='</ul><a href="#step-file"><span data-l="en">Continue: load OS files</span><span data-l="fr">Continuer : charger les OS</span></a></div>'
 html=html.replace('<div class="super-toolbar">',listing+'<div class="super-toolbar">',1)
 html=html.replace('<h2 id="h1s" data-i18n="s1">What do you want to install?</h2>', '<h2 id="h1s"><span data-l="en">Your firmware</span><span data-l="fr">Votre firmware</span></h2>')
 html=html.replace('</body>',f'<script src="macro-fine-data.js?v={STAMP}"></script><script src="macro-fine-release.js?v={STAMP}"></script><script src="level-pan-main-data.js?v={STAMP}"></script><script src="pad-mode-data.js?v={STAMP}"></script><script src="pad-mode.js?v={STAMP}"></script><script src="genie-entropy-data.js?v={STAMP}"></script><script src="genie-entropy.js?v={STAMP}"></script><script src="midi-safety-data.js?v={STAMP}"></script><script src="midi-safety-release.js?v={STAMP}"></script><script src="step-rec-solo-data.js?v={STAMP}"></script><script src="step-rec-solo-main.js?v={STAMP}"></script><script src="fixed-main-image.js?v={STAMP}"></script></body>')
 files['index.html']=html
 files['midi-safety-data.js']=(out/'midi-safety-data.js').read_text(encoding='utf-8')
 files['midi-safety-release.js']=(ROOT/'tools/web/midi-safety-release.js').read_text(encoding='utf-8')
 files['step-rec-solo-main.js']=(ROOT/'tools/web/step-rec-solo-main.js').read_text(encoding='utf-8')
 files['step-rec-solo-data.js']=(out/'step-rec-solo-data.js').read_text(encoding='utf-8')
 files['fixed-main-image.js']=FIXED_IMAGE_JS
 files['genie-entropy-data.js']=(out/'genie-entropy-data.js').read_text(encoding='utf-8')
 files['genie-entropy.js']=(ROOT/'tools/web/genie-entropy.js').read_text(encoding='utf-8')
 files['pad-mode-data.js']=(out/'pad-mode-data.js').read_text(encoding='utf-8')
 files['pad-mode.js']=(ROOT/'tools/web/pad-mode.js').read_text(encoding='utf-8')
